contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(uint256 amount, address to) public payable {
        require(to != address(0) && to != address(c), "beneficiary must be a distinct nonzero address");
        require(amount > 0, "amount must be positive");

        uint256 before = c.imBalances(to);

        bool reverted;
        try c.supplyTokenTo(amount, to) {
            reverted = false;
        } catch {
            reverted = true;
        }

        if (!reverted) {
            uint256 afterBal = c.imBalances(to);
            assert(afterBal >= before);
        } else {
            assert(c.imBalances(to) == before);
        }
    }

    receive() external payable {}
}

