contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    function run(address to, uint256 supplyAmount, uint256 queryAddrSeed) public payable {
        require(to != address(0), "beneficiary must be nonzero");
        require(queryAddrSeed != 0, "query address must be nonzero");

        address queryAddr = address(uint160(queryAddrSeed));

        uint256 rateBefore = c.savings().exchangeRate();
        uint256 balBefore = c.balanceOfToken(queryAddr);

        c.supplyTokenTo(supplyAmount, to);

        uint256 balAfter = c.balanceOfToken(to);

        assert(balAfter * 1e18 >= (supplyAmount + (balBefore * rateBefore) / 1e18) * rateBefore);
    }

    receive() external payable {}
}

