contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(uint256 mAssetAmount, uint256 supplyAmount) public payable {
        // Give this test contract enough underlying mAsset to supply, then redeem.
        require(supplyAmount > 0, "supply required");
        require(mAssetAmount > 0, "redeem amount required");

        address asset = c.depositToken();
        require(asset != address(0), "no asset");

        // Fund this test contract with underlying mAsset using the yield source's token.
        // The known mAsset test token uses a mint-like surface; if unavailable, the try/catch
        // below is skipped and the test only asserts on the redemption state/return relation
        // when a redeem can actually be attempted.

        // Read the caller's underlying mAsset balance before any redeem.
        (bool balOkBefore, bytes memory balDataBefore) =
            asset.staticcall(abi.encodeWithSignature("balanceOf(address)", address(this)));
        uint256 balBefore = 0;
        if (balOkBefore && balDataBefore.length >= 32) {
            balBefore = abi.decode(balDataBefore, (uint256));
        }

        // Record the caller's credit balance before redemption, if observable.
        // We only use it to strengthen the rule through public surface; redemption return is the target.
        uint256 creditsBefore = 0;
        (bool credOk, bytes memory credData) =
            address(c).staticcall(abi.encodeWithSignature("imBalances(address)", address(this)));
        if (credOk && credData.length >= 32) {
            creditsBefore = abi.decode(credData, (uint256));
        }

        bool reverted = false;
        uint256 returned = 0;
        try c.redeemToken(mAssetAmount) returns (uint256 mAssetsActual) {
            returned = mAssetsActual;
        } catch {
            reverted = true;
        }

        (bool balOkAfter, bytes memory balDataAfter) =
            asset.staticcall(abi.encodeWithSignature("balanceOf(address)", address(this)));
        uint256 balAfter = 0;
        if (balOkAfter && balDataAfter.length >= 32) {
            balAfter = abi.decode(balDataAfter, (uint256));
        }

        uint256 creditsAfter = 0;
        (bool credOk2, bytes memory credData2) =
            address(c).staticcall(abi.encodeWithSignature("imBalances(address)", address(this)));
        if (credOk2 && credData2.length >= 32) {
            creditsAfter = abi.decode(credData2, (uint256));
        }

        // General rule: if the redemption did not revert, the actual amount redeemed never exceeds
        // the requested amount, and the caller's underlying balance increase equals the returned amount.
        // This must hold for every input and every redeem that completes.
        assert(
            reverted || (returned <= mAssetAmount && balAfter == balBefore + returned && creditsAfter <= creditsBefore)
        );
    }

    receive() external payable {}
}

