contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(uint256 mAssetAmount) public payable {
        // Precondition: a non-zero redemption makes the mAsset delta meaningful and avoids
        // a degenerate zero-loop; the rule itself is general for all mAssetAmount.
        // Read-only snapshots are taken before the deciding call.
        address mAssetAddr = c.mAsset();
        uint256 balBefore = IERC20(mAssetAddr).balanceOf(address(c));

        // Snapshot the externally-observed state needed for the rule.
        // Only view/pure public getters are used: mAsset(), balanceOfToken() is non-view
        // (external but not view) so we cannot call it here; use the public getter for the
        // underlying token balance instead.
        uint256 senderMAssetBefore = IERC20(mAssetAddr).balanceOf(address(this));

        // The deciding call. Amount may be zero; that is fine, the rule covers it.
        (bool success, bytes memory returndata) = address(c).call(
            abi.encodeWithSelector(c.redeemToken.selector, mAssetAmount)
        );

        uint256 returned = 0;
        if (success && returndata.length >= 32) {
            returned = abi.decode(returndata, (uint256));
        }

        uint256 balAfter = IERC20(mAssetAddr).balanceOf(address(c));

        // General rule: whenever redeemToken completes without reverting, the mAsset amount
        // returned to the caller equals the decrease of c's own mAsset balance.  This is the
        // core accounting invariant: redeemToken pulls exactly what it hands out.
        // The no-underflow form (balBefore - balAfter) is safe only when balAfter <= balBefore,
        // which itself is the second half of the same conservation statement; we assert that
        // ordering explicitly so the subtraction is not a hidden precondition.
        assert(!success || (balAfter <= balBefore && returned == balBefore - balAfter));
    }

    receive() external payable {}
}

