        // Determine whether the caller has enough credits to allow the redeem to succeed.
        uint256 selfCreditsBefore = c.imBalances(address(this));
        uint256 exchangeRate = savings.exchangeRate();

        // We cannot easily know the exact creditsBurned ahead of time; so we use a try/catch:
        // if redeemToken succeeds, the savings.redeemUnderlying will have burned some credits.
        // To make the assertion meaningful, we capture creditsBurned via the savings return value
        // by calling redeemUnderlying ourselves? No—we must only observe through c.
        // Instead, we rely on the event or on the change in imBalances? But we cannot read the
        // return value of savings.redeemUnderlying directly from c.redeemToken.
        // However, the contract stores imBalances[msg.sender] -= creditsBurned, so we can
        // observe the reduction in the caller's imBalances.

        // We need the reduction to be some value; we cannot predict it without simulating
        // savings. So we assert a weaker but general property: if the call succeeds, then
        // the caller's imBalances decreased by some positive amount and no other address changed.
        // But we must end with exactly one assert over params, read values, and revert flags.

        // Let's build a test that checks: if redeemToken(amount) succeeds, then
        // imBalances(other) remains unchanged, and imBalances(address(this)) decreased.
        // (The latter might be 0 if amount is 0 but creditsBurned could be 0).

        bool reverted;
        try c.redeemToken(amount) {
            reverted = false;
        } catch {
            reverted = true;
        }

        uint256 otherAfter = c.imBalances(other);
        uint256 selfAfter = c.imBalances(address(this));

        // General rule: if the redeem succeeded, then the credit balance of any address other than
        // the caller must be exactly the same as before, and the caller's credit balance must be
        // less than or equal to the before value (it decreases by creditsBurned which is >= 0).
        assert(
            reverted ||
            (otherAfter == otherBefore && selfAfter <= selfCreditsBefore)
        );
    }

    receive() external payable {}
}

