    function run(uint256 amount) public payable {
        // Drive c through the public entry `redeemToken`.
        uint256 beforeImBalance = c.imBalances(address(this));
        uint256 beforeAddrBalance = c.mAsset().balanceOf(address(c));

        uint256 mAssetsActual;
        bool reverted;
        try c.redeemToken(amount) returns (uint256 actual) {
            mAssetsActual = actual;
