            reverted = true;
        }

        uint256 afterImBalance = c.imBalances(address(this));
        uint256 afterAddrBalance = c.mAsset().balanceOf(address(c));

        // General rule: if the call succeeded, the caller's imBalances key must have
        // decreased (or stayed the same only if no credits were burned, which cannot
        // happen for a successful redeem) and the returned amount must equal the
        // increase in c's mAsset balance. The caller's imBalances key cannot increase
        // as a result of redeemToken.
        assert(
            reverted ||
            (mAssetsActual == afterAddrBalance - beforeAddrBalance &&
             afterAddrBalance >= beforeAddrBalance &&
             afterImBalance <= beforeImBalance)
        );
    }

    receive() external payable {}
}

