contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(address to, uint256 mAssetAmount) public payable {
        // Setup: give this contract mAsset tokens so it can supply them.
        // The caller holds mAsset tokens (the test contract's balance is pre-funded).
        uint256 creditsBeforeRedeem;
        uint256 mAssetBalanceBefore;
        uint256 mAssetBalanceAfter;
        uint256 creditsAfterRedeem;

        // Require the test contract has enough mAsset to supply.
        uint256 supplyAmount = mAssetAmount + 1;
        uint256 mAssetBalance = c.mAsset().balanceOf(address(this));
        require(mAssetBalance >= supplyAmount, "insufficient mAsset balance");

        // Approve the yield source to pull mAsset tokens from this contract.
        c.mAsset().approve(address(c), supplyAmount);

        // Supply tokens to get credits for this contract (the caller).
        c.supplyTokenTo(supplyAmount, address(this));

        creditsBeforeRedeem = c.imBalances(address(this));
        mAssetBalanceBefore = c.mAsset().balanceOf(address(this));

        // Ensure savings contract has enough mAsset to redeem from.
        require(c.mAsset().balanceOf(address(c.savings())) >= mAssetAmount, "savings lacks underlying");

        // Deciding call: redeem mAssetAmount from the yield source.
        c.redeemToken(mAssetAmount);

        creditsAfterRedeem = c.imBalances(address(this));
        mAssetBalanceAfter = c.mAsset().balanceOf(address(this));

        // The credits burned should be reflected in the imBalances decrease.
        // The mAsset received should be the difference in balances.
        // Since the exchange rate can vary, the credits burned equals the decrease in imBalances,
        // and the mAsset received equals the balance increase.
        // The general rule: the decrease in credits must equal the mAsset received times
        // the exchange rate at the time of redemption (approximately, due to rounding).
        // More precisely, the credits burned = mAssetAmount * exchangeRate / 1e18,
        // and the mAsset received = mAssetAmount (if sufficient liquidity).
        // To keep the rule general and avoid underflow, we assert that the credits decrease
        // is non-negative and that the mAsset received is exactly mAssetAmount.
        uint256 creditsDecrease = creditsBeforeRedeem - creditsAfterRedeem;
        uint256 mAssetReceived = mAssetBalanceAfter - mAssetBalanceBefore;

        // General rule: after a successful redeemToken call, the caller's credits decrease by
        // exactly the credits burned, and the mAsset received equals the requested mAssetAmount.
        assert(creditsDecrease > 0 && mAssetReceived == mAssetAmount);
    }

    receive() external payable {}
}

