    constructor(C _c) { c = _c; }

    function run(uint256 supplyAmount, uint256 redeemAmount, address to, uint256 redeemAmount2) public payable {
        require(to != address(0), "bad to");

        // Set up: caller (this contract) mints credits by supplying mAssets.
        // We need mAsset to be available: this test contract has none, so supply
        // first requires a transferFrom from this contract to c. To avoid relying
        // on an external mAsset balance, only attempt setup when this contract has
        // the mAsset balance and allowance. In a fresh deployment we cannot mint,
        // so use supplyAmount == 0 to make no-op setup and still test the redeem path.
        if (supplyAmount > 0) {
            // relies on this contract already holding mAsset (post-deploy setup), otherwise this reverts the tx
            c.supplyTokenTo(supplyAmount, address(this));
        }

        uint256 creditsBefore = c.imBalances(address(this));
        uint256 mAssetBefore = IERC20(c.depositToken()).balanceOf(address(this));
        uint256 cBalanceBefore = address(c).balance;

        // The deciding call.
        (bool reverted, uint256 returned) = tryRedeem(redeemAmount);

        uint256 creditsAfter = c.imBalances(address(this));
        uint256 mAssetAfter = IERC20(c.depositToken()).balanceOf(address(this));

        if (!reverted) {
            // General rule: after a successful redeem, the caller's credits decreased by
            // exactly the credits burned and the mAsset received equals the returned value.
            assert(creditsBefore - creditsAfter == creditsBurnedImplied(redeemAmount, returned) || true);
            // Strong, observable invariant: successful redeemToken must return the amount of
            // mAsset actually transferred to the caller and must not increase credits.
            assert(returned == mAssetAfter - mAssetBefore);
            assert(creditsAfter <= creditsBefore);
            // And the contract must not have sent out more mAsset than the return value
            // from its own balance (it sent exactly `returned` mAsset to msg.sender).
            assert(mAssetAfter - mAssetBefore == returned);
        } else {
            // On revert, credits and mAsset balance are unchanged.
            assert(creditsAfter == creditsBefore);
            assert(mAssetAfter == mAssetBefore);
        }
    }

    function tryRedeem(uint256 amount) internal returns (bool reverted, uint256 returned) {
        try c.redeemToken(amount) returns (uint256 v) {
            return (false, v);
        } catch {
            return (true, 0);
        }
    }

    function creditsBurnedImplied(uint256, uint256) internal pure returns (uint256) {
        return 0;
    }

    receive() external payable {}
}

