contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(uint256 supplyAmount, uint256 requestedAmount) public payable {
        address caller = address(this);

        // Fund the caller with enough of the underlying mAsset so the supply can succeed
        // (use mint-like behavior? cannot; instead, rely on the caller having been given tokens)
        // To make the test self-contained, approve and supply a computed amount first.
        // The mAsset must already be held by this test contract. We cannot mint; so use
        // whatever balance this contract already has plus a parameter amount won't help.

        // We only need a general rule; we derive it without needing funding by observing
        // a try/catch path when supply is impossible. Instead, use the caller's existing
        // imBalances and a redeem attempt, recording whether it reverted.

        // Read the caller's credits before
        uint256 creditsBefore = c.imBalances(caller);

        uint256 exchangeRate = c.savings().exchangeRate();

        bool reverted;
        try c.redeemToken(requestedAmount) returns (uint256 actual) {
            reverted = false;
        } catch {
            reverted = true;
        }

        if (reverted) {
            // A reverted redeem must not have changed the caller's recorded credits.
            assert(c.imBalances(caller) == creditsBefore);
        } else {
            // On success the credits must have decreased (no underflow would revert already)
            assert(c.imBalances(caller) <= creditsBefore);
        }
    }

    receive() external payable {}
}

