contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(uint256 supplyAmount, uint256 redeemAmount) public {
        // fund this test contract with enough mAsset so supplyTokenTo can pull tokens
        IERC20 mAsset = IERC20(c.depositToken());

        // cannot call an interface that is not declared; use the public getter address
        // depositToken() returns the underlying mAsset address.
        // We only call view functions on c inside require/assert; state-changing calls are top-level.
        // Provide tokens to this contract via the savings contract's underlying token.
        // Since mAsset is external and we cannot assume its total supply, we only exercise the
        // path when the test contract already holds enough tokens. In a fresh deployment
        // the checker controls initial balances; we guard the setup with a require on the
        // observable mAsset balance of this contract.
        require(mAsset.balanceOf(address(this)) >= supplyAmount, "test needs mAsset");

        // Supply underlying into c so the caller has imBalances to redeem against.
        c.supplyTokenTo(supplyAmount, address(this));

        // Read the before-state through public view functions.
        uint256 balanceBefore = mAsset.balanceOf(address(this));
        uint256 imBalanceBefore = c.imBalances(address(this));

        bool reverted;
        uint256 mAssetsActual;
        try c.redeemToken(redeemAmount) returns (uint256 r) {
            mAssetsActual = r;
            reverted = false;
        } catch {
            reverted = true;
        }

        uint256 balanceAfter = mAsset.balanceOf(address(this));
        uint256 imBalanceAfter = c.imBalances(address(this));

        assert(
            reverted
                ? imBalanceAfter == imBalanceBefore && balanceAfter == balanceBefore
                : balanceAfter >= balanceBefore + mAssetsActual && imBalanceAfter <= imBalanceBefore
        );
    }
}

contract InvMutTest {
