    }

    function run(uint256 supplyAmount, uint256 redeemAmount) public {
        // Fund this test contract with mAsset so supplyTokenTo can pull tokens.
        // The caller must pre-approve and pre-fund; assert observable token balance path only when possible.
        IERC20 mAsset = IERC20(c.depositToken());

        // Precondition: this test contract must hold at least supplyAmount of the underlying mAsset,
        // and must have approved c to spend it. We check only the balance (public view) here.
        require(mAsset.balanceOf(address(this)) >= supplyAmount, "need mAsset");

        // Top-level setup: supply underlying into c so caller (this) has credits (imBalances).
        c.supplyTokenTo(supplyAmount, address(this));

        // Top-level read-only reads before the deciding call.
        uint256 mAssetBalanceBefore = mAsset.balanceOf(address(this));
        uint256 imBalanceBefore = c.imBalances(address(this));

        bool reverted;
        uint256 returned;
        try c.redeemToken(redeemAmount) returns (uint256 r) {
            returned = r;
            reverted = false;
        } catch {
            reverted = true;
        }

        uint256 mAssetBalanceAfter = mAsset.balanceOf(address(this));
        uint256 imBalanceAfter = c.imBalances(address(this));

        // General rule: if redeemToken succeeded, the returned amount equals the mAsset balance increase,
        // and the caller's credits decreased (credits burned) with the invariant that the credits burned
        // correspond to the returned underlying; on failure state is unchanged.
        assert(
            reverted
                ? (mAssetBalanceAfter == mAssetBalanceBefore && imBalanceAfter == imBalanceBefore)
                : (mAssetBalanceAfter == mAssetBalanceBefore + returned && imBalanceAfter <= imBalanceBefore)
        );
    }

    receive() external payable {}
}

