        // Use the exchange rate to convert a credit amount to an mAsset amount? No, not needed.
        // We just call redeemToken with the user-supplied redeemAmount, but cap it to something plausible.
        // The caller must have enough credits to cover the redeem.

        uint256 returned;
        bool reverted;
        try c.redeemToken(redeemAmount) returns (uint256 r) {
            returned = r;
            reverted = false;
        } catch {
            reverted = true;
        }

        uint256 creditsAfter = c.imBalances(address(this));

