        // the non-owner revert path when caller != address(this).
        bool reverted;
        if (caller == address(this)) {
            // owner path: must not revert
            try c.approveMax() { reverted = false; } catch { reverted = true; }
        } else {
            // non-owner path: must revert (caller is not the owner)
            try c.approveMax() { reverted = true; } catch { reverted = false; }
        }
        // General rule: a non-owner caller always reverts, owner never reverts.
        // Equivalently: the revert flag is exactly the negation of caller == owner.
        assert(reverted == (caller != address(this)));
    }
}

