contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    receive() external payable {}

    function run(uint256 supplyAmount, uint256 redeemAmount) public payable {
        require(redeemAmount > 0, "redeem amount must be positive");

        // Set up the state needed for the rule: the test contract must hold enough
        // credits for the caller. Supply first if requested; supplyTokenTo pulls
        // underlying tokens from the test contract, so they must be provided here.
        if (supplyAmount > 0) {
            IERC20 mAsset = c.mAsset();
            // Acquire the underlying mAsset from the savings contract's underlying token
            // by using the test's Ether? No, use already-transferred tokens: the test
            // must already hold mAsset tokens. We transfer from our own balance.
            // Since we cannot read c's private state, we only rely on public getters.
            mAsset.transfer(address(c), supplyAmount);
            // The transfer above is an external call on the token, not c; it doesn't change c.
            // Now call c.supplyTokenTo to credit the test contract.
            c.supplyTokenTo(supplyAmount, address(this));
        }

        // Record the underlying mAsset balance of c before the deciding call.
        uint256 balanceBefore = c.mAsset().balanceOf(address(c));

        // Record the test contract's own balance of the underlying mAsset before the call.
        uint256 selfBalanceBefore = c.mAsset().balanceOf(address(this));

        // The deciding call: redeemToken. It updates C's state and transfers mAsset to msg.sender.
        uint256 returned = c.redeemToken(redeemAmount);

        // Measure how much underlying actually arrived to the test contract.
        uint256 selfBalanceAfter = c.mAsset().balanceOf(address(this));

        // The property: the value returned by redeemToken equals the increase in
        // the caller's underlying balance during the call. This must hold for any
        // successful (non-reverting) call.
        assert(returned == selfBalanceAfter - selfBalanceBefore);
    }
}

