        if (balBefore >= balAfter) {
            observedDelta = balBefore - balAfter;
        } else {
            observedDelta = 0;
        }

        // If the redeem did not revert, the consumed credits burn is exactly the balance decrease.
        // Since we supply exactly mAssetAmount credits first, the burn equals creditsToUnderlying(amount)
        // but we only assert the observable balance-decrease relation.
        if (!reverted) {
            assert(balAfter <= balBefore && observedDelta > 0);
        } else {
            assert(balAfter == balBefore);
        }
    }

    receive() external payable {}
}

