contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    function run(uint256 mAssetAmount, address to) public payable {
        require(mAssetAmount > 0, "amount must be positive");
        require(to != address(0), "to must be nonzero");

        // Fund this test contract with mAsset by supplying it as c's first depositor.
        address mAsset = c.depositToken();
        (bool okSupply, ) = mAsset.call(abi.encodeWithSignature("transfer(address,uint256)", address(c), mAssetAmount));
        require(okSupply, "seed transfer to c failed");
        c.supplyTokenTo(mAssetAmount, to);

        uint256 balanceBefore = 0;
        (bool okBalBefore, bytes memory retBefore) = mAsset.staticcall(abi.encodeWithSignature("balanceOf(address)", address(c)));
        require(okBalBefore, "balanceOf before failed");
        balanceBefore = abi.decode(retBefore, (uint256));

        uint256 actual = 0;
        bool reverted = false;
        try c.redeemToken(mAssetAmount) returns (uint256 r) {
            actual = r;
        } catch {
            reverted = true;
        }

        uint256 balanceAfter = 0;
        (bool okBalAfter, bytes memory retAfter) = mAsset.staticcall(abi.encodeWithSignature("balanceOf(address)", address(c)));
        require(okBalAfter, "balanceOf after failed");
        balanceAfter = abi.decode(retAfter, (uint256));

        // If the call completed, the returned amount must equal the increase in c's mAsset balance.
        assert(reverted || actual == balanceAfter - balanceBefore);
    }

    receive() external payable {}
}

